fn find_min(a: &mut [i32], from: usize, to: usize) -> usize {
    // Ensure the range is valid and non‐empty
    assert!(from < to && to <= a.len(), "invalid range");

    // Initialize with the first element in the subarray
    let mut min_index = from;
    let mut min_value = a[from];

    // Scan the rest of the subarray
    for i in (from + 1)..to {
        if a[i] < min_value {
            min_value = a[i];
            min_index = i;
        }
    }

    min_index
}

