    #[test]
    fn basic_tests() {
        let mut data = [5, 3, 8, 1, 4, 1, 7];
        // Look in the full range: minimum is 1 at index 3 (or 5).
        let idx = find_min(&mut data, 0, data.len());
        assert!([3, 5].contains(&idx));
        assert_eq!(data[idx], 1);

        // Look in a smaller range where the minimum is unique
        let idx = find_min(&mut data, 2, 5);
        assert_eq!(idx, 3);
        assert_eq!(data[idx], 1);

        // Single‐element range
        let idx = find_min(&mut data, 4, 5);
        assert_eq!(idx, 4);
        assert_eq!(data[idx], 4);
    }

    #[test]
